    "FieldSchema" = '{"$schema":"http://json-schema.org/draft-07/schema#","type":"object","properties":{"BaseURL":{"type":"string","title":"Base URL","description":"Customer''s netFORUM Enterprise base URL (e.g., https://customer.netforum.example.com). The connector appends the xWeb SOAP path /xweb/secure/netForumXML.asmx and POSTs a SOAP Authenticate envelope there to obtain the session token.","format":"uri","order":0},"Username":{"type":"string","title":"Username","description":"netFORUM xWeb API username. Sent as the userName element in the SOAP Authenticate envelope body.","order":1},"Password":{"type":"string","title":"Password","description":"netFORUM xWeb API password. Sent as the password element in the SOAP Authenticate envelope body — not HTTP Basic — to mint the session token.","isSecret":true,"order":2}},"required":["BaseURL","Username","Password"]}'
